function validate([m, n, guards, walls]) {
  if (!Number.isInteger(m) || !Number.isInteger(n) || m < 1 || n < 1 || m > 100000 || n > 100000) return 'm and n are between 1 and 10^5.';
  if (m * n < 2 || m * n > 100000) return 'm * n must be between 2 and 10^5.';
  if (guards.length < 1 || walls.length < 1 || guards.length > 50000 || walls.length > 50000) return 'guards and walls each need 1 to 5 * 10^4 positions.';
  if (guards.length + walls.length > m * n) return 'There are more guards and walls than cells.';
  const seen = new Set();
  for (const cell of [...guards, ...walls]) {
    if (!Array.isArray(cell) || cell.length !== 2 || !cell.every(Number.isInteger)) return 'Each position is [row, col].';
    const [row, col] = cell;
    if (row < 0 || row >= m || col < 0 || col >= n) return 'Every position must lie inside the grid.';
    const key = row * n + col;
    if (seen.has(key)) return 'All guard and wall positions must be distinct.';
    seen.add(key);
  }
  return null;
}

