function countUnguarded(m, n, guards, walls) {
  const EMPTY = 0;
  const SEEN = 1;
  const BLOCKED = 2;
  const grid = Array.from({ length: m }, () => new Array(n).fill(EMPTY));
  for (const [row, col] of guards) {
    grid[row][col] = BLOCKED;
  }
  for (const [row, col] of walls) {
    grid[row][col] = BLOCKED;
  }

  const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  for (const [row, col] of guards) {
    for (const [dr, dc] of directions) {
      let r = row + dr;
      let c = col + dc;
      while (r >= 0 && r < m && c >= 0 && c < n && grid[r][c] !== BLOCKED) {
        grid[r][c] = SEEN;
        r += dr;
        c += dc;
      }
    }
  }

  let count = 0;
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      if (grid[r][c] === EMPTY) {
        count++;
      }
    }
  }
  return count;
}

