function countUnguarded(m, n, guards, walls) {
  const kindAt = (r, c) => {
    if (guards.some(g => g[0] === r && g[1] === c)) return 'guard';
    if (walls.some(w => w[0] === r && w[1] === c)) return 'wall';
    return 'free';
  };
  let total = 0;
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      if (kindAt(r, c) !== 'free') continue;
      let watched = false;
      for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        for (let k = 1; ; k++) {
          const rr = r + dr * k, cc = c + dc * k;
          if (rr < 0 || rr >= m || cc < 0 || cc >= n) break;
          const kind = kindAt(rr, cc);
          if (kind === 'wall') break;
          if (kind === 'guard') { watched = true; break; }
        }
      }
      if (!watched) total++;
    }
  }
  return total;
}

