function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  let m, n, guardCount, wallCount;
  if (size === 'large') {
    m = pick(1, 2000);
    n = pick(Math.max(1, Math.ceil(5000 / m)), Math.floor(100000 / m));
    guardCount = pick(1, rand() < 0.5 ? 60 : 2000);
    wallCount = pick(1, 2000);
  } else {
    do { m = pick(1, 6); n = pick(1, 6); } while (m * n < 2);
    guardCount = pick(1, Math.max(1, Math.min(4, m * n - 1)));
    wallCount = pick(1, Math.max(1, Math.min(5, m * n - guardCount)));
  }
  const used = new Set();
  const place = (amount) => {
    const cells = [];
    while (cells.length < amount) {
      const key = pick(0, m * n - 1);
      if (used.has(key)) continue;
      used.add(key);
      cells.push([Math.floor(key / n), key % n]);
    }
    return cells;
  };
  const guards = place(guardCount);
  const walls = place(wallCount);
  return [m, n, guards, walls];
}
